static __inline effect_color_t projectile_clamp_color(effect_color_t color)
{
    if (color.r < 0.0f) {
        color.r = 0.0f;
    } else if (color.r > 1.0f) {
        color.r = 1.0f;
    }
    if (color.g < 0.0f) {
        color.g = 0.0f;
    } else if (color.g > 1.0f) {
        color.g = 1.0f;
    }
    if (color.b < 0.0f) {
        color.b = 0.0f;
    } else if (color.b > 1.0f) {
        color.b = 1.0f;
    }
    if (color.a < 0.0f) {
        color.a = 0.0f;
    } else if (color.a > 1.0f) {
        color.a = 1.0f;
    }
    return color;
}

